const alarms = [
    { topic: 'sim/plant/PumpTrip_P1A/active', name: 'PumpTrip_P1A' },
    { topic: 'sim/plant/BreakerFault_MCC3/active', name: 'BreakerFault_MCC3' },
    { topic: 'sim/plant/HighLevel_Thickener/active', name: 'HighLevel_Thickener' },
    { topic: 'sim/plant/VibrationHigh_Screen2/active', name: 'VibrationHigh_Screen2' },
    { topic: 'sim/plant/EStop_Conveyor7/active', name: 'EStop_Conveyor7' },
    { topic: 'sim/plant/MagnetiteLevel_Low/active', name: 'MagnetiteLevel_Low' }
];

// Pick a random alarm
const alarm = alarms[Math.floor(Math.random() * alarms.length)];

// Activate it
const activateMsg = {
    topic: alarm.topic,
    payload: true
};

// Schedule ack after 3-10s random delay
const ackDelay = 3000 + Math.floor(Math.random() * 7000);
// Schedule clear after 5-15s random delay
const clearDelay = 5000 + Math.floor(Math.random() * 10000);

// Randomly choose lifecycle path:
//   Path A (60%): ack first, then clear
//   Path B (40%): clear first, then ack
const ackFirst = Math.random() < 0.6;

const ackMsg = {
    payload: { action: 'ack', source: alarm.topic },
    _alarm: alarm.name,
    _delay: ackFirst ? ackDelay : clearDelay + ackDelay
};

const clearMsg = {
    topic: alarm.topic,
    payload: false,
    _alarm: alarm.name,
    _delay: ackFirst ? clearDelay + ackDelay : clearDelay
};

// Store scheduled actions in context for the delay nodes
node.status({ text: `${alarm.name} (${ackFirst ? 'ack-first' : 'clear-first'})` });

// Output 1: activate now
// Output 2: ack (with delay metadata)
// Output 3: clear (with delay metadata)
return [activateMsg, ackMsg, clearMsg];

const delay = msg._delay || 5000;
const alarmName = msg._alarm || 'unknown';

return new Promise(resolve => {
    const timerId = setTimeout(() => {
        node.status({ text: `ack ${alarmName} after ${(delay/1000).toFixed(1)}s` });
        delete msg._delay;
        delete msg._alarm;
        resolve(msg);
    }, delay);

    // Clean up on node close
    node.on('close', () => clearTimeout(timerId));
});

const delay = msg._delay || 8000;
const alarmName = msg._alarm || 'unknown';

return new Promise(resolve => {
    const timerId = setTimeout(() => {
        node.status({ text: `clear ${alarmName} after ${(delay/1000).toFixed(1)}s` });
        delete msg._delay;
        delete msg._alarm;
        resolve(msg);
    }, delay);

    // Clean up on node close
    node.on('close', () => clearTimeout(timerId));
});

// Route the ack to the correct alarm node based on source topic
const source = msg.payload.source;
const routes = {
    'sim/plant/PumpTrip_P1A/active': 0,
    'sim/plant/BreakerFault_MCC3/active': 1,
    'sim/plant/HighLevel_Thickener/active': 2,
    'sim/plant/VibrationHigh_Screen2/active': 3,
    'sim/plant/EStop_Conveyor7/active': 4,
    'sim/plant/MagnetiteLevel_Low/active': 5
};

const outputs = [null, null, null, null, null, null];
const idx = routes[source];
if (idx !== undefined) {
    outputs[idx] = msg;
}
return outputs;
